    data = sys.stdin.read().split()
    if not data:
        return

    v = int(data[0])
    e = int(data[1])

    if e == 0:
        print(0)
        return
    if v <= 6:
        print(e)
        return

    m = [[] for _ in range(v + 1)]
    idx = 2
    for _ in range(e):
        a = int(data[idx])
        b = int(data[idx + 1])
        idx += 2
        m[a].append(b)
        m[b].append(a)

    f = False
    noOfVertices = 20

    for j in range(1, 8):
        a7 = m[j]
        for i in range(1, 8):
            if i == j:
                continue
            other = m[i]
